import{_ as e,o as d,c as o,a2 as r}from"./chunks/framework.CWWEQfK7.js";const m=JSON.parse('{"title":"Command reference","description":"Find common installation, runtime, and validation commands for Ershu deployment, backend components, frontend, and documentation.","frontmatter":{"page_id":"reference-commands","title":"Command reference","description":"Find common installation, runtime, and validation commands for Ershu deployment, backend components, frontend, and documentation."},"headers":[],"relativePath":"en/reference/commands.md","filePath":"en/reference/commands.md","lastUpdated":1786627803000}'),c={name:"en/reference/commands.md"};function n(s,t,a,u,h,i){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="command-reference" tabindex="-1">Command reference <a class="header-anchor" href="#command-reference" aria-label="Permalink to &quot;Command reference&quot;">​</a></h1><p>Server commands use the fixed paths from the quick deployment. Run development commands from the repository named by their table. Backend work uses UV throughout. Do not copy one component&#39;s lock file into another component.</p><h2 id="installed-linux-server" tabindex="-1">Installed Linux server <a class="header-anchor" href="#installed-linux-server" aria-label="Permalink to &quot;Installed Linux server&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Purpose</th><th>Command</th></tr></thead><tbody><tr><td>Install the current release</td><td><code>sudo bash deploy/systemd/install.sh --uv-bin &quot;$(command -v uv)&quot;</code></td></tr><tr><td>Start the complete backend</td><td><code>sudo systemctl enable --now ershu.target</code></td></tr><tr><td>Inspect backend status</td><td><code>sudo systemctl status ershu-api ershu-worker ershu-mcp</code></td></tr><tr><td>Restart the complete backend</td><td><code>sudo systemctl restart ershu.target</code></td></tr><tr><td>Stop the complete backend</td><td><code>sudo systemctl stop ershu.target</code></td></tr><tr><td>Follow backend logs</td><td><code>journalctl -u ershu-api -u ershu-worker -u ershu-mcp -f</code></td></tr><tr><td>Inspect infrastructure</td><td><code>sudo systemctl status ershu-infrastructure</code></td></tr><tr><td>Enable scheduled polling</td><td><code>sudo systemctl enable --now ershu-poller.service</code></td></tr><tr><td>Show migration heads</td><td><code>/opt/ershu/current/.venv/bin/ershu-db heads</code></td></tr><tr><td>Show the target database revision</td><td><code>sudo -u ershu sh -c &#39;cd /etc/ershu &amp;&amp; /opt/ershu/current/.venv/bin/ershu-db current&#39;</code></td></tr></tbody></table><p>See the <a href="/en/guide/quick-start">Linux server deployment</a> for the complete order.</p><h2 id="backend-component-checks" tabindex="-1">Backend component checks <a class="header-anchor" href="#backend-component-checks" aria-label="Permalink to &quot;Backend component checks&quot;">​</a></h2><p>Run the install command in the matching repository before the checks.</p><table tabindex="0"><thead><tr><th>Repository</th><th>Install</th><th>Tests</th><th>Code and format</th><th>Build</th></tr></thead><tbody><tr><td><code>ershu-core</code></td><td><code>uv sync --locked</code></td><td><code>uv run pytest -m &quot;not integration&quot;</code></td><td><code>uv run ruff check src tests</code><br><code>uv run ruff format --check src tests</code></td><td><code>uv build --no-sources</code></td></tr><tr><td><code>ershu-api</code></td><td><code>uv sync --locked --extra dev</code></td><td><code>uv run --extra dev pytest -q</code></td><td><code>uv run --extra dev ruff check src tests</code><br><code>uv run --extra dev ruff format --check src tests</code></td><td><code>uv build --wheel</code></td></tr><tr><td><code>ershu-worker</code></td><td><code>uv sync --locked --extra dev</code></td><td><code>uv run pytest -q</code></td><td><code>uv run ruff check src tests scripts</code><br><code>uv run ruff format --check src tests scripts</code></td><td><code>uv build --no-sources</code></td></tr><tr><td><code>ershu-mcp</code></td><td><code>uv sync --locked</code></td><td><code>uv run pytest -q</code></td><td><code>uv run ruff check src tests</code><br><code>uv run ruff format --check src tests</code></td><td><code>uv build --no-sources</code></td></tr></tbody></table><p>Tests that use external services require separate PostgreSQL, Milvus, or Docker setup. Ordinary unit tests do not replace them.</p><h2 id="frontend-repository-frontend" tabindex="-1">Frontend repository <code>frontend</code> <a class="header-anchor" href="#frontend-repository-frontend" aria-label="Permalink to &quot;Frontend repository `frontend`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Purpose</th><th>Command</th></tr></thead><tbody><tr><td>Install from the lock file</td><td><code>npm ci</code></td></tr><tr><td>Start development</td><td><code>npm run dev</code></td></tr><tr><td>Run tests</td><td><code>npm test</code></td></tr><tr><td>Check code and types</td><td><code>npm run lint</code></td></tr><tr><td>Check formatting</td><td><code>npm run format:check</code></td></tr><tr><td>Build for production</td><td><code>npm run build</code></td></tr><tr><td>Preview the build</td><td><code>npm run preview</code></td></tr></tbody></table><p>The Chinese development URL is <code>http://localhost:3000/#/zh</code>, and English is <code>http://localhost:3000/#/en</code>.</p><h2 id="documentation-repository-ershu-docs" tabindex="-1">Documentation repository <code>ershu-docs</code> <a class="header-anchor" href="#documentation-repository-ershu-docs" aria-label="Permalink to &quot;Documentation repository `ershu-docs`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Purpose</th><th>Command</th></tr></thead><tbody><tr><td>Install from the lock file</td><td><code>npm ci</code></td></tr><tr><td>Start local writing</td><td><code>npm run dev</code></td></tr><tr><td>Check bilingual pages, links, and typography</td><td><code>npm run check:content</code></td></tr><tr><td>Check formatting</td><td><code>npm run format:check</code></td></tr><tr><td>Build for production</td><td><code>npm run build</code></td></tr><tr><td>Run every check</td><td><code>npm run check</code></td></tr><tr><td>Preview the build</td><td><code>npm run preview</code></td></tr></tbody></table><p>The development server uses <code>http://127.0.0.1:5173</code> by default.</p>',15)])])}const p=e(c,[["render",n]]);export{m as __pageData,p as default};
